/*
 * Lockfiles generated by real package managers (test/fixtures/lockfiles/protocols/generate.sh)
 * for one project that uses every dependency kind: registry, range, npm: alias, scoped,
 * GitHub, file: directory and tarball, bundled, link:, portal:, workspace, peer and a
 * Yarn builtin patch. Each manager locks the same registry packages, so each must parse
 * to the same registry identities and get the same findings.
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { parseLockfileText } from "../src/lockfile/index.js";
import type { ParsedLockfile } from "../src/lockfile/index.js";
import { checkLockfile } from "../src/checks/lockfile.js";
import { indexPackages } from "../src/iocs.js";
import { checkSoakLockfiles } from "../src/soak.js";
import { fx, testCtx } from "./helpers.js";

const FILE = { npm: "package-lock.json", pnpm: "pnpm-lock.yaml", yarn: "yarn.lock" } as const;
/** fixture dir -> [lockfile name, package count from an independent parser (JSON.parse / js-yaml / header count)] */
const FIXTURES: Record<string, [string, number]> = {
  npm6: [FILE.npm, 24],
  npm10: [FILE.npm, 26],
  npm12: [FILE.npm, 26],
  pnpm7: [FILE.pnpm, 22],
  pnpm8: [FILE.pnpm, 22],
  pnpm9: [FILE.pnpm, 22],
  pnpm11: [FILE.pnpm, 22],
  pnpm12: [FILE.pnpm, 22],
  "pnpm11-env": [FILE.pnpm, 20],
  "pnpm8-tarball": [FILE.pnpm, 2],
  "pnpm11-tarball": [FILE.pnpm, 2],
  "pnpm11-runtime": [FILE.pnpm, 13], // is-number plus one entry per platform binary of the node runtime
  "pnpm11-runtime-deno": [FILE.pnpm, 5],
  "pnpm11-runtime-bun": [FILE.pnpm, 7],
  "yarn4-longkey": [FILE.yarn, 62],
  "pnpm11-local": [FILE.pnpm, 2],
  "yarn4-local": [FILE.yarn, 3],
  yarn1: [FILE.yarn, 26],
  yarn4: [FILE.yarn, 28],
  "empty-npm": [FILE.npm, 0],
  "empty-pnpm": [FILE.pnpm, 0],
  "empty-yarn1": [FILE.yarn, 0],
  "empty-yarn4": [FILE.yarn, 1],
};
/** The fixtures that lock the full shared project; the others each cover one layout. */
const MAIN = ["npm6", "npm10", "npm12", "pnpm7", "pnpm8", "pnpm9", "pnpm11", "pnpm12", "yarn1", "yarn4"];

const text = (dir: string): string => readFileSync(fx("lockfiles", "protocols", dir, (FIXTURES[dir] as [string, number])[0]), "utf8");
const load = (dir: string): ParsedLockfile => {
  const l = parseLockfileText((FIXTURES[dir] as [string, number])[0], text(dir));
  assert.ok(l, dir);
  return l;
};
const byName = (l: ParsedLockfile, name: string) => l.packages.filter((p) => p.name === name);

const REGISTRY = [
  "@nodelib/fs.scandir@2.1.5", "@nodelib/fs.stat@2.0.5", "function-bind@1.1.2", "hasown@2.0.4", "is-core-module@2.17.0",
  "is-number@7.0.0", "js-tokens@4.0.0", "loose-envify@1.4.0", "object-assign@4.1.1", "path-parse@1.0.7", "queue-microtask@1.2.3",
  "react-dom@17.0.2", "react@17.0.2", "resolve@1.22.8", "run-parallel@1.2.0", "scheduler@0.20.2", "supports-preserve-symlinks-flag@1.0.0",
  "to-regex-range@5.0.1",
];

test("every real lockfile parses to the package count an independent parser finds", () => {
  for (const [dir, [, count]] of Object.entries(FIXTURES)) assert.equal(load(dir).packages.length, count, dir);
});

test("every manager locks the same registry identities (aliases, peer suffixes and multi-descriptor headers resolved)", () => {
  for (const dir of MAIN) {
    const registry = load(dir).packages.filter((p) => !p.local && !p.bundled && (!p.resolved || p.resolved.startsWith("https://registry.")));
    const ids = new Set(registry.map((p) => `${p.name}@${p.version}`));
    // yarn ignores bundleDependencies and locks bundler's `ms` as a registry package
    const expected = dir.startsWith("yarn") ? [...REGISTRY, "ms@2.1.3"] : REGISTRY;
    assert.deepEqual([...ids].sort(), [...expected].sort(), dir);
  }
});

test("IOC matching finds aliased, scoped multi-descriptor and peer-suffixed packages in every format", () => {
  const ctx = testCtx();
  ctx.pkgIndex = indexPackages([{ id: "t", wave: "t", source: "https://example.test/ioc", packages: { "is-number": ["7.0.0"], "@nodelib/fs.stat": ["2.0.5"], "react-dom": ["17.0.2"] } }]);
  for (const dir of MAIN) {
    const hits = new Set(checkLockfile(load(dir), ctx).filter((f) => f.ruleId === "WS-LK-001").map((f) => f.key));
    assert.deepEqual([...hits].sort(), ["@nodelib/fs.stat@2.0.5", "is-number@7.0.0", "react-dom@17.0.2"], dir);
  }
});

test("npm: aliases resolve to the real package in lockfile v1 and v3", () => {
  for (const dir of ["npm6", "npm10"]) {
    const l = load(dir);
    assert.equal(byName(l, "isnum").length, 0, dir);
    assert.equal(byName(l, "is-number").filter((p) => p.version === "7.0.0").length, 2, `${dir}: direct dependency and alias`);
  }
});

test("yarn: aliases resolve to the real package in classic and berry", () => {
  for (const dir of ["yarn1", "yarn4"]) assert.equal(byName(load(dir), "isnum").length, 0, dir);
  assert.equal(byName(load("yarn1"), "is-number").length, 2, "yarn1 keeps the alias as its own block");
});

test("yarn berry: names come from the resolution, not the quoted multi-descriptor header", () => {
  const l = load("yarn4");
  assert.ok(!l.packages.some((p) => p.name.includes('"') || p.name.includes(",")));
  assert.deepEqual(byName(l, "@nodelib/fs.stat").map((p) => p.version), ["2.0.5"]);
  assert.match(byName(l, "escape-string-regexp")[0]?.resolved ?? "", /^https:\/\/github\.com\/sindresorhus\/escape-string-regexp\.git#commit=/);
});

test("yarn berry: builtin patch: entries are the registry package they patch", () => {
  const resolve = byName(load("yarn4"), "resolve");
  assert.equal(resolve.length, 2, "the npm entry and its builtin<compat/resolve> patch");
  for (const p of resolve) assert.deepEqual(p, { name: "resolve", version: "1.22.8" });
});

test("local dependencies (file: dirs, link:, portal:, workspaces) are local in every format", () => {
  const locals: Record<string, string[]> = {
    npm6: ["localdep"],
    npm10: ["libs/localdep", "localdep", "packages/wsa", "wsa"],
    pnpm7: ["localdep"],
    pnpm8: ["localdep"],
    pnpm11: ["localdep"],
    yarn1: ["linkdep", "localdep"],
    yarn4: ["fixture-root", "linkdep", "localdep", "portaldep", "wsa"],
  };
  for (const [dir, names] of Object.entries(locals)) {
    assert.deepEqual(load(dir).packages.filter((p) => p.local).map((p) => p.name).sort(), names, dir);
  }
});

test("every format reports the same findings: git deps medium, file: tarballs high, nothing for local deps", () => {
  const want = ["WS-LK-002 high bundler", "WS-LK-002 high tardep", "WS-LK-002 medium escape-string-regexp"];
  for (const dir of MAIN) {
    const got = checkLockfile(load(dir), testCtx())
      .filter((f) => !(dir === "yarn1" && f.ruleId === "WS-LK-003" && /^(bundler|tardep)@/.test(f.key ?? ""))) // yarn 1 writes no integrity for file: tarballs
      .map((f) => `${f.ruleId} ${f.severity} ${(f.key.split(" ")[0] as string).replace(/@[^@]*$/, "")}`);
    assert.deepEqual([...new Set(got)].sort(), want, dir);
  }
});

test("GitHub dependencies recorded as codeload tarballs (yarn 1, pnpm) are git sources, and soak reports them as unverifiable", async () => {
  for (const dir of ["yarn1", "pnpm7", "pnpm12"]) {
    const l = load(dir);
    const codeload = l.packages.filter((p) => p.resolved?.startsWith("https://codeload.github.com/"));
    assert.ok(codeload.length > 0, dir);
    const f = checkLockfile({ ...l, packages: codeload }, testCtx());
    assert.deepEqual(f.map((x) => `${x.ruleId} ${x.severity}`), codeload.map(() => "WS-LK-002 medium"), dir);
    // A git source has no registry publish time: soak must say so (fail closed), not ask the registry or skip it.
    const asked: string[] = [];
    const registry = (async (url: string | URL) => (asked.push(String(url)), new Response("{}", { status: 404 }))) as typeof fetch;
    const soak = await checkSoakLockfiles([{ ...l, packages: codeload }], { minAgeMs: 72 * 3_600_000, registry: "https://registry.npmjs.org", now: new Date("2026-10-01T00:00:00Z"), fetchImpl: registry });
    assert.deepEqual(asked, [], dir);
    assert.deepEqual(soak.findings.map((x) => x.ruleId), codeload.map(() => "WS-SK-002"), dir);
  }
});

test("pnpm: git, file: and v5 peer-suffixed entries get the package's own name and version", () => {
  for (const dir of ["pnpm7", "pnpm8", "pnpm9", "pnpm11", "pnpm12"]) {
    const l = load(dir);
    assert.deepEqual(byName(l, "escape-string-regexp").map((p) => p.version), ["5.0.0"], dir);
    assert.deepEqual(byName(l, "tardep").map((p) => p.version), ["1.0.0"], dir);
    assert.deepEqual(byName(l, "react-dom").map((p) => p.version), ["17.0.2"], dir);
  }
});

test("pnpm: both YAML documents are read when pnpm locks its own package manager first", () => {
  const ids = load("pnpm11-env").packages.map((p) => `${p.name}@${p.version}`);
  assert.ok(ids.includes("pnpm@11.16.0") && ids.includes("is-number@7.0.0"), ids.join(" "));
});

test("projects without registry dependencies parse to no packages instead of throwing", () => {
  for (const dir of ["empty-npm", "empty-pnpm", "empty-yarn1"]) assert.deepEqual(load(dir).packages, [], dir);
  assert.deepEqual(load("empty-yarn4").packages.map((p) => p.local), [true]);
});

const IOC = (packages: Record<string, string[]>) => indexPackages([{ id: "t", wave: "t", source: "https://example.test/ioc", packages }]);

test("pnpm: registry entries with a tarball URL (lockfileIncludeTarballUrl) are the registry package", async () => {
  const ctx = testCtx();
  ctx.pkgIndex = IOC({ "is-number": ["7.0.0"], "@nodelib/fs.stat": ["2.0.5"] });
  for (const dir of ["pnpm8-tarball", "pnpm11-tarball"]) {
    const l = load(dir);
    assert.deepEqual(l.packages.map((p) => `${p.name}@${p.version} ${p.resolved ?? ""}`).sort(), [
      "@nodelib/fs.stat@2.0.5 https://registry.npmjs.org/@nodelib/fs.stat/-/fs.stat-2.0.5.tgz",
      "is-number@7.0.0 https://registry.npmjs.org/is-number/-/is-number-7.0.0.tgz",
    ], dir);
    assert.deepEqual(checkLockfile(l, ctx).map((f) => `${f.ruleId} ${f.key}`).sort(), ["WS-LK-001 @nodelib/fs.stat@2.0.5", "WS-LK-001 is-number@7.0.0"], dir);
    // The soak gate must age-check these as registry packages: it asks the registry for both and verifies both.
    const asked: string[] = [];
    const registry = (async (url: string | URL) => {
      const name = decodeURIComponent(String(url).replace("https://registry.npmjs.org/", ""));
      asked.push(name);
      const version = name === "is-number" ? "7.0.0" : "2.0.5";
      // soak compares the locked integrity with the registry's, so the mock serves the real one
      const dist = { integrity: l.packages.find((p) => p.name === name)?.integrity };
      return new Response(JSON.stringify({ name, time: { [version]: "2020-01-01T00:00:00.000Z" }, versions: { [version]: { dist } } }));
    }) as typeof fetch;
    const soak = await checkSoakLockfiles([l], { minAgeMs: 72 * 3_600_000, registry: "https://registry.npmjs.org", now: new Date("2026-10-01T00:00:00Z"), fetchImpl: registry });
    assert.deepEqual(asked.sort(), ["@nodelib/fs.stat", "is-number"], dir);
    assert.deepEqual(soak.evidence.map((e) => `${e.name}@${e.version} ${e.status}`).sort(), ["@nodelib/fs.stat@2.0.5 ok", "is-number@7.0.0 ok"], dir);
  }
});

test("file: dependencies: a directory path with spaces and a tarball whose own version is not semver (pnpm 11, yarn 4)", () => {
  for (const dir of ["pnpm11-local", "yarn4-local"]) {
    const l = load(dir);
    assert.deepEqual(byName(l, "oddver").map((p) => `${p.version} ${p.resolved}`), [`1.0 file:${dir === "yarn4-local" ? "./oddver-1.0.tgz#./" : ""}oddver-1.0.tgz`], dir);
    assert.deepEqual(byName(l, "spaced").map((p) => p.local), [true], dir);
  }
});

test("pnpm: every binary of a devEngines runtime is reported with its download URL, and official ones raise nothing", () => {
  const raw = text("pnpm11-runtime");
  assert.match(raw, /^ {2}node@runtime:22\.11\.0:\n {4}resolution:\n {6}type: variations$/m);
  for (const [dir, name, binaries] of [["pnpm11-runtime", "node", 12], ["pnpm11-runtime-deno", "deno", 5], ["pnpm11-runtime-bun", "bun", 7]] as const) {
    const l = load(dir);
    const runtimes = l.packages.filter((p) => p.runtime);
    assert.equal(runtimes.length, binaries, dir);
    for (const p of runtimes) {
      assert.equal(p.name, name, dir);
      assert.match(p.version, /^runtime:\d/, dir);
      assert.match(p.integrity ?? "", /^sha256-/, dir);
      assert.match(p.resolved ?? "", /^https:\/\//, dir);
    }
    assert.deepEqual(checkLockfile(l, testCtx()), [], dir);
  }
  // a project whose only locked dependency is the runtime
  const runtimeOnly = raw.replace(/^ {6}is-number:\n(?: {8}.*\n){2}/m, "").replace(/^ {2}is-number@7\.0\.0:\n(?: {4}.*\n)+\n/gm, "").replace(/^ {2}is-number@7\.0\.0: \{\}\n/m, "");
  assert.doesNotMatch(runtimeOnly, /is-number/);
  assert.equal(parseLockfileText(FILE.pnpm, runtimeOnly)?.packages.length, 12);
});

test("yarn berry: a header long enough to be written as an explicit `? key` is read", () => {
  const raw = text("yarn4-longkey");
  assert.match(raw, /^\? "ms@npm:>=2\.0\.0 <3, .{1000,}"\n:\n {2}version: 2\.1\.3$/m);
  assert.deepEqual(byName(load("yarn4-longkey"), "ms"), [{ name: "ms", version: "2.1.3" }]);
  assert.throws(() => parseLockfileText(FILE.yarn, raw.replace(/^:$/m, "")), /expected `:`/);
});
